package com.hdfclife.ledger.config;

import com.hdfclife.ledger.domain.*; import com.hdfclife.ledger.repo.*; import org.springframework.boot.CommandLineRunner; import org.springframework.context.annotation.Bean; import org.springframework.context.annotation.Configuration; import org.springframework.core.env.Environment; import java.util.*;
@Configuration
public class DataSeeder {
    @Bean CommandLineRunner seed(CustomerRepository customers, PolicyRepository policies, RiderRepository riders, Environment env) { return args -> { if (policies.count() > 0) return;
        Map<String,Customer> people = new LinkedHashMap<>(); people.put("Anita Sharma", customers.save(new Customer("Anita Sharma", "anita.sharma@hdfclife.example"))); people.put("Rahul Mehta", customers.save(new Customer("Rahul Mehta", "rahul.mehta@hdfclife.example"))); people.put("Priya Nair", customers.save(new Customer("Priya Nair", "priya.nair@hdfclife.example"))); people.put("Vikram Singh", customers.save(new Customer("Vikram Singh", "vikram.singh@hdfclife.example"))); people.put("Sneha Patel", customers.save(new Customer("Sneha Patel", "sneha.patel@hdfclife.example")));
        Policy p1 = policies.save(new Policy("HDFC-LIFE-1001", people.get("Anita Sharma"), "TERM", 18500, "Active")); Policy p2 = policies.save(new Policy("HDFC-LIFE-1002", people.get("Rahul Mehta"), "ULIP", 42000, "Active")); Policy p3 = policies.save(new Policy("HDFC-LIFE-1003", people.get("Priya Nair"), "ENDOWMENT", 27000, "Lapsed")); Policy p4 = policies.save(new Policy("HDFC-LIFE-1004", people.get("Vikram Singh"), "TERM", 15200, "Active")); Policy p5 = policies.save(new Policy("HDFC-LIFE-1005", people.get("Sneha Patel"), "ULIP", 36000, "Active")); Policy p6 = policies.save(new Policy("HDFC-LIFE-1006", people.get("Anita Sharma"), "ENDOWMENT", 22000, "Pending"));
        p1.getRiders().add(riders.findByCode("ACCIDENT_COVER").orElseThrow()); p1.getRiders().add(riders.findByCode("WAIVER_OF_PREMIUM").orElseThrow()); policies.save(p1);
        System.out.println("Active profile -> " + Arrays.stream(env.getActiveProfiles()).findFirst().orElse("dev")); System.out.println("Policy count -> " + policies.count()); System.out.println("Customer count -> " + customers.count()); System.out.println("Lookup HDFC-LIFE-1004 customer -> " + p4.getCustomer().getFullName()); System.out.println("Active count -> " + policies.findByStatusOrderByPolicyNoAsc("Active").size()); System.out.println("TERM count -> " + policies.findByProductTypeOrderByPolicyNoAsc("TERM").size()); System.out.println("Anita Sharma policy count -> " + policies.findByCustomer_FullNameOrderByPolicyNoAsc("Anita Sharma").size()); System.out.println("minPremium=20000 policy numbers -> " + policies.findWithPremiumAtLeast(20000).stream().map(Policy::getPolicyNo).toList()); System.out.println("HDFC-LIFE-1001 rider codes -> " + p1.getRiders().stream().map(Rider::getCode).sorted().toList());
    }; }
}
